/**
 * @file op_vtable_map.c
 * @brief Maps FB_OP_* IDs to named vtable fields; populates ext_ops[].
 *
 * Generated 237-entry table mapping every named function-pointer field in
 * fb_backend_vtable_t to its FB_OP_* constant, enabling uniform O(1)
 * op-level dispatch via vtable->ext_ops[].
 *
 * @copyright Copyright (c) 2025
 * @license MIT OR Apache-2.0
 */

