#define K_OP_FIELD_MAP_COUNT \
    ((int)(sizeof(k_op_field_map) / sizeof(k_op_field_map[0])))

void fb_vtable_sync_ext_ops(fb_backend_vtable_t *v) {
    if (!v) return;
    for (int i = 0; i < K_OP_FIELD_MAP_COUNT; i++) {
        uint32_t  op_id = k_op_field_map[i].op_id;
        ptrdiff_t off   = k_op_field_map[i].offset;
        fb_generic_fn fn = NULL;
        memcpy(&fn, (const char *)v + off, sizeof(fb_generic_fn));
        /* Mirror named typed field → CBLAS convention slot (only if empty). */
        if (fn != NULL && v->ext_ops[op_id][FB_CONV_CBLAS] == NULL) {
            v->ext_ops[op_id][FB_CONV_CBLAS] = fn;
        }
    }
}

/**
 * fb_vtable_fill_named_from_ext_ops — reverse of fb_vtable_sync_ext_ops.
 *
 * After fb_enumerate_and_populate() has filled ext_ops[][FB_CONV_CBLAS]
 * from a DLL scan, call this to propagate those pointers into the named
 * typed vtable fields (vtable->saxpy, vtable->sgemm, …) that the judge
 * and dispatch code call directly.  Only fills slots that are currently NULL.
 */
void fb_vtable_fill_named_from_ext_ops(fb_backend_vtable_t *v) {
  if (!v)
    return;
  for (int i = 0; i < K_OP_FIELD_MAP_COUNT; i++) {
    uint32_t op_id = k_op_field_map[i].op_id;
    ptrdiff_t off = k_op_field_map[i].offset;
    fb_generic_fn fn = v->ext_ops[op_id][FB_CONV_CBLAS];
    if (fn == NULL)
      continue;
    /* Only fill the named field if it is currently empty. */
    fb_generic_fn existing = NULL;
    memcpy(&existing, (const char *)v + off, sizeof(fb_generic_fn));
    if (existing == NULL) {
      memcpy((char *)v + off, &fn, sizeof(fb_generic_fn));
    }
  }
}

fb_generic_fn fb_vtable_get_op(const fb_backend_vtable_t *v, uint32_t op_id) {
    if (!v || op_id >= (uint32_t)FB_JUDGE_MAX_OPERATIONS) return NULL;
    /* Prefer CBLAS convention; fall back to Fortran. */
    if (v->ext_ops[op_id][FB_CONV_CBLAS]   != NULL) return v->ext_ops[op_id][FB_CONV_CBLAS];
    return v->ext_ops[op_id][FB_CONV_FORTRAN];
}

